import React, { useState } from 'react';

const TranscriptAnalyzer = () => {
  const [transcript, setTranscript] = useState('');
  const [summary, setSummary] = useState(null);

  const analyzeTone = (text) => {
    const positiveWords = ['great', 'excellent', 'improvement', 'success', 'well', 'positive', 'growth'];
    const negativeWords = ['challenge', 'difficult', 'concern', 'problem', 'struggle', 'issue'];
    
    const positiveCount = positiveWords.reduce((count, word) => 
      count + (text.toLowerCase().match(new RegExp(word, 'g')) || []).length, 0);
    const negativeCount = negativeWords.reduce((count, word) => 
      count + (text.toLowerCase().match(new RegExp(word, 'g')) || []).length, 0);
    
    return positiveCount > negativeCount ? 'Positive' : 
           negativeCount > positiveCount ? 'Constructive' : 'Neutral';
  };

  const extractMetrics = (text) => {
    const metrics = [];
    const patterns = [
      /(\d+%)\s*(conversion|close rate|attendance)/gi,
      /(\$[\d,]+)\s*(revenue|sales)/gi,
      /(\d+)\s*(calls|meetings|demos|appointments)/gi
    ];

    patterns.forEach(pattern => {
      const matches = [...text.matchAll(pattern)];
      matches.forEach(match => metrics.push(`${match[1]} ${match[2]}`));
    });

    return metrics;
  };

  const findChallenges = (text) => {
    const sentences = text.match(/[^.!?]+[.!?]+/g) || [];
    return sentences.find(s => 
      s.toLowerCase().includes('challenge') || 
      s.toLowerCase().includes('difficult') || 
      s.toLowerCase().includes('struggling')
    ) || 'No specific challenges identified';
  };

  const findKeyTakeaway = (text) => {
    const sentences = text.match(/[^.!?]+[.!?]+/g) || [];
    const actionWords = ['need to', 'should', 'will', 'must', 'going to'];
    
    const actionSentence = sentences.find(s => 
      actionWords.some(word => s.toLowerCase().includes(word))
    );
    
    return actionSentence || 'Focus on improving key metrics';
  };

  const analyzeTranscript = () => {
    setSummary({
      tone: analyzeTone(transcript),
      metrics: extractMetrics(transcript),
      mainChallenge: findChallenges(transcript),
      keyTakeaway: findKeyTakeaway(transcript)
    });
  };

  return (
    <div className="max-w-2xl mx-auto bg-white p-6 rounded-lg shadow-lg">
      <h2 className="text-2xl font-bold mb-4">1:1 Meeting Analysis</h2>
      
      <div className="space-y-4">
        <textarea 
          className="w-full h-48 p-2 border rounded"
          placeholder="Paste meeting transcript here..."
          value={transcript}
          onChange={(e) => setTranscript(e.target.value)}
        />
        
        <button
          className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700"
          onClick={analyzeTranscript}
        >
          Analyze Transcript
        </button>

        {summary && (
          <div className="space-y-4 mt-4">
            <div>
              <h3 className="font-bold">Conversation Tone</h3>
              <p>{summary.tone}</p>
            </div>
            
            <div>
              <h3 className="font-bold">Metrics Discussed</h3>
              <ul className="list-disc pl-4">
                {summary.metrics.map((metric, i) => (
                  <li key={i}>{metric}</li>
                ))}
              </ul>
            </div>
            
            <div>
              <h3 className="font-bold">Main Challenge</h3>
              <p>{summary.mainChallenge}</p>
            </div>
            
            <div>
              <h3 className="font-bold">Key Takeaway</h3>
              <p>{summary.keyTakeaway}</p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default TranscriptAnalyzer;
